cat > tests/backend/test-server.js <<'EOF'
'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');

const { createServer } = require('../../server/server.js');

const repositoryRoot = path.resolve(__dirname, '..', '..');

async function startBackendServer(overrides = {}) {
  const server = createServer({
    dataPath: path.join(repositoryRoot, 'data', 'levels.json'),
    staticRoot: path.join(repositoryRoot, 'web'),
    ...overrides,
  });

  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });

  assert.equal(server.listening, true);

  const address = server.address();
  return {
    server,
    origin: "'`http://127.0.0.1:${address.port}`,
    async stop() {
      if (!server.listening) {
        return;
      }
      await new Promise((resolve, reject) => {
        server.close((error) => {
          if (error) {
            reject(error);
            return;
          }
          resolve();
        });
      });
    },
  };
}

module.exports = { startBackendServer };
EOF
cat > tests/backend/levels-api.test.js <<'"'EOF'
'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');

const { startBackendServer } = require('./test-server.js');

const repositoryRoot = path.resolve(__dirname, '..', '..');
const allowedDifficulties = new Set(['简单', '普通', '困难']);

test('GET /api/levels returns five validated levels as JSON', async () => {
  const backend = await startBackendServer({
    dataPath: path.join(repositoryRoot, 'data', 'levels.json'),
  });

  try {
    const response = await fetch("'`${backend.origin}/api/levels`);

    assert.equal(response.status, 200);
    assert.equal(response.headers.get('"'content-type'), 'application/json; charset=utf-8');

    const levels = await response.json();
    assert.equal(Array.isArray(levels), true);
    assert.equal(levels.length, 5);

    const ids = new Set();
    for (const level of levels) {
      assert.equal(typeof level.id, 'string');
      assert.notEqual(level.id.trim(), '');
      assert.equal(ids.has(level.id), false);
      ids.add(level.id);

      assert.equal(typeof level.name, 'string');
      assert.notEqual(level.name.trim(), '');
      assert.equal(typeof level.difficulty, 'string');
      assert.equal(allowedDifficulties.has(level.difficulty), true);
      assert.equal(typeof level.unlocked, 'boolean');
    }
  } finally {
    await backend.stop();
  }
});
EOF
node --test tests/backend/levels-api.test.js"

