'use strict';

const http = require('node:http');
const fs = require('node:fs/promises');
const path = require('node:path');

const ALLOWED_DIFFICULTIES = new Set(['简单', '普通', '困难']);
const LEVEL_DATA_ERROR = {
  code: 'LEVEL_DATA_UNAVAILABLE',
  message: '暂时无法加载关卡数据，请稍后重试',
};

function validateLevels(value) {
  if (!Array.isArray(value) || value.length !== 5) {
    return false;
  }

  const ids = new Set();
  return value.every((level) => {
    if (level === null || typeof level !== 'object' || Array.isArray(level)) {
      return false;
    }

    if (typeof level.id !== 'string' || level.id.trim() === '' || ids.has(level.id)) {
      return false;
    }
    ids.add(level.id);

    return (
      typeof level.name === 'string' &&
      level.name.trim() !== '' &&
      typeof level.difficulty === 'string' &&
      ALLOWED_DIFFICULTIES.has(level.difficulty) &&
      typeof level.unlocked === 'boolean'
    );
  });
}

async function readLevels(dataPath) {
  const source = await fs.readFile(dataPath, 'utf8');
  const value = JSON.parse(source);

  if (!validateLevels(value)) {
    throw new Error('Invalid level data');
  }

  return value;
}

function sendText(response, statusCode, body) {
  response.writeHead(statusCode, {
    'content-type': 'text/plain; charset=utf-8',
    'content-length': Buffer.byteLength(body),
  });
  response.end(body);
}

function contentTypeFor(filePath) {
  const extension = path.extname(filePath).toLowerCase();
  if (extension === '.html') {
    return 'text/html; charset=utf-8';
  }
  if (extension === '.js') {
    return 'text/javascript; charset=utf-8';
  }
  return 'application/octet-stream';
}

async function serveStatic(request, response, staticRoot) {
  if (request.method !== 'GET') {
    sendText(response, 405, '不支持的请求方法');
    return;
  }

  const requestPath = request.url.split('?')[0];
  const relativePath = requestPath === '/' ? 'index.html' : requestPath.replace(/^\//, '');
  const root = path.resolve(staticRoot);
  const filePath = path.resolve(root, relativePath);

  if (filePath !== root && !filePath.startsWith(`${root}${path.sep}`)) {
    sendText(response, 403, '静态资源访问被拒绝');
    return;
  }

  try {
    const content = await fs.readFile(filePath);
    response.writeHead(200, {
      'content-type': contentTypeFor(filePath),
      'content-length': content.length,
    });
    response.end(content);
  } catch {
    sendText(response, 404, '静态资源不存在');
  }
}

function sendJson(response, statusCode, value) {
  const body = JSON.stringify(value);
  response.writeHead(statusCode, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(body),
  });
  response.end(body);
}

function createServer(options = {}) {
  const dataPath = options.dataPath ?? path.join(process.cwd(), 'data', 'levels.json');
  const staticRoot = options.staticRoot ?? path.join(process.cwd(), 'web');

  return http.createServer(async (request, response) => {
    if (request.url === '/api/levels') {
      if (request.method !== 'GET') {
        sendJson(response, 405, {
          error: {
            code: 'METHOD_NOT_ALLOWED',
            message: '不支持的请求方法',
          },
        });
        return;
      }

      try {
        const levels = await readLevels(dataPath);
