+'use strict';
+
+const assert = require('node:assert/strict');
+const { readFile } = require('node:fs/promises');
+const path = require('node:path');
+const { test } = require('node:test');
+
+const { initLevelSelect, validateLevels } = require('../../web/level-select.js');
+
+const repositoryRoot = path.resolve(__dirname, '..', '..');
+
+class FakeElement {
+  constructor(tagName) {
+    this.tagName = tagName;
+    this.children = [];
+    this.attributes = new Map();
+    this.textContent = '';
+    this.disabled = false;
+  }
+
+  setAttribute(name, value) {
+    this.attributes.set(name, String(value));
+  }
+
+  getAttribute(name) {
+    return this.attributes.has(name) ? this.attributes.get(name) : null;
+  }
+
+  appendChild(child) {
+    this.children.push(child);
+    return child;
+  }
+
+  replaceChildren(...children) {
+    this.children = [...children];
+  }
+}
+
+function createDocument() {
+  const elements = new Map([
+    ['loading', new FakeElement('div')],
+    ['level-list', new FakeElement('ul')],
+    ['error-message', new FakeElement('div')],
+  ]);
+  elements.get('error-message').setAttribute('aria-live', 'polite');
+
+  return {
+    createElement(tagName) {
+      return new FakeElement(tagName);
+    },
+    getElementById(id) {
+      return elements.get(id) ?? null;
+    },
+  };
+}
+
+function createFetchDouble(levels, options = {}) {
+  const requests = [];
+  async function fetchImpl(input, init) {
+    requests.push({ input, init });
+    if (options.rejectWith) {
+      throw options.rejectWith;
+    }
+    return {
+      ok: options.ok ?? true,
+      status: options.status ?? 200,
+      json: async () => levels,
+    };
+  }
+
+  return { fetchImpl, requests };
+}
+
+function validLevels() {
+  return [
+    { id: 'level-1', name: '初始之地', difficulty: '简单', unlocked: true },
+    { id: 'level-2', name: '风影回廊', difficulty: '简单', unlocked: true },
+    { id: 'level-3', name: '波之国航路', difficulty: '普通', unlocked: true },
+    { id: 'level-4', name: '中忍考场', difficulty: '困难', unlocked: false },
+    { id: 'level-5', name: '终结之谷', difficulty: '困难', unlocked: false },
+  ];
+}
+
+async function renderWithFetch(levels, options = {}) {
+  const document = createDocument();
+  const originalContainers = [
+    document.getElementById('loading'),
+    document.getElementById('level-list'),
+    document.getElementById('error-message'),
+  ];
+  const double = createFetchDouble(levels, options);
+  await initLevelSelect({ document, fetchImpl: double.fetchImpl });
+  assert.deepEqual(
+    [
+      document.getElementById('loading'),
+      document.getElementById('level-list'),
+      document.getElementById('error-message'),
+    ],
+    originalContainers
+  );
+  return { document, requests: double.requests };
+}
+
+test('initLevelSelect shows loading state before rendering five named levels', async () => {
+  const document = createDocument();
+  let resolveJson;
+  const jsonPromise = new Promise((resolve) => {
+    resolveJson = resolve;
+  });
+  const requests = [];
+  const fetchImpl = async (input, init) => {
+    requests.push({ input, init });
+    return { ok: true, status: 200, json: () => jsonPromise };
+  };
+
+  const rendered = initLevelSelect({ document, fetchImpl });
+
+  assert.equal(requests.length, 1);
+  assert.deepEqual(requests[0], { input: '/api/levels', init: undefined });
+  assert.equal(document.getElementById('loading').getAttribute('aria-hidden'), 'false');
+  assert.equal(document.getElementById('level-list').children.length, 0);
+  assert.equal(document.getElementById('error-message').getAttribute('aria-live'), 'polite');
+  assert.equal(document.getElementById('error-message').textContent, '');
+
+  resolveJson(validLevels());
+  await rendered;
+
+  assert.equal(document.getElementById('loading').getAttribute('aria-hidden'), 'true');
+  assert.equal(document.getElementById('error-message').textContent, '');
+  const summaries = document
+    .getElementById('level-list')
+    .children.map((item) => {
+      const button = item.children[0];
+      const name = button.children[0];
+      const difficulty = name.children[0];
+      return `${name.textContent}（${difficulty.textContent}）`;
+    });
+  assert.deepEqual(summaries, [
+    '初始之地（简单）',
+    '风影回廊（简单）',
+    '波之国航路（普通）',
+    '中忍考场（困难）',
+    '终结之谷（困难）',
+  ]);
+});
+
+test('initLevelSelect renders locked levels as unselectable buttons', async () => {
+  const { document } = await renderWithFetch(validLevels());
+
+  const items = document.getElementById('level-list').children;
+  assert.equal(items[3].getAttribute('class'), 'level-item locked');
+  assert.equal(items[3].children[0].disabled, true);
+  assert.equal(items[3].children[0].getAttribute('data-level-id'), 'level-4');
+  assert.equal(items[4].getAttribute('class'), 'level-item locked');
+  assert.equal(items[4].children[0].disabled, true);
+  assert.equal(items[4].children[0].getAttribute('data-level-id'), 'level-5');
+});
+
+test('initLevelSelect reports fetch failures without replacing the page containers', async () => {
+  const { document, requests } = await renderWithFetch(validLevels(), {
+    rejectWith: new TypeError('network unavailable'),
+  });
+
+  assert.equal(requests.length, 1);
+  assert.equal(document.getElementById('loading').getAttribute('aria-hidden'), 'true');
+  assert.equal(document.getElementById('error-message').textContent, '关卡加载失败，请稍后重试');
+  assert.equal(document.getElementById('level-list').children.length, 0);
+  assert.notEqual(document.getElementById('error-message'), null);
+});
+
+test('initLevelSelect reports non-200 responses without losing the page frame', async () => {
+  const { document } = await renderWithFetch(validLevels(), {
+    ok: false,
+    status: 500,
+  });
+
+  assert.equal(document.getElementById('loading').getAttribute('aria-hidden'), 'true');
+  assert.equal(document.getElementById('error-message').textContent, '关卡加载失败，请稍后重试');
+  assert.equal(document.getElementById('level-list').children.length, 0);
+});
+
+test('initLevelSelect reports invalid level payloads without losing the page frame', async () => {
+  const invalidPayloads = [
+    null,
+    [],
+    [
+      { id: 'level-1', name: '初始之地', difficulty: '简单', unlocked: true },
+      { id: 'level-1', name: '风影回廊', difficulty: '简单', unlocked: true },
+      { id: 'level-3', name: '波之国航路', difficulty: '普通', unlocked: true },
+      { id: 'level-4', name: '中忍考场', difficulty: '困难', unlocked: false },
+      { id: 'level-5', name: '终结之谷', difficulty: '困难', unlocked: false },
+    ],
+    [{ id: '', name: '初始之地', difficulty: '简单', unlocked: true }],
+    [{ id: 'level-1', name: '', difficulty: '简单', unlocked: true }],
+    [{ id: 'level-1', name: '初始之地', difficulty: '简单', unlocked: 'true' }],
+  ];
+
+  for (const levels of invalidPayloads) {
+    const { document } = await renderWithFetch(levels);
+
+    assert.equal(document.getElementById('loading').getAttribute('aria-hidden'), 'true');
+    assert.equal(
+      document.getElementById('error-message').textContent,
+      '关卡数据格式不正确，请稍后重试'
+    );
+    assert.equal(document.getElementById('level-list').children.length, 0);
+  }
+});
+
+test('web/index.html contains the loading, level-list, and error containers', async () => {
+  const html = await readFile(path.join(repositoryRoot, 'web', 'index.html'), 'utf8');
+
+  assert.equal(html.includes('id="loading"'), true);
+  assert.equal(html.includes('id="level-list"'), true);
+  assert.equal(html.includes('id="error-message"'), true);
+});
+
+test('web/index.html imports level-select.js and initializes it with page dependencies', async () => {
+  const html = await readFile(path.join(repositoryRoot, 'web', 'index.html'), 'utf8');
+  const match = html.match(/<script type="module">([\s\S]*?)<\/script>/u);
+
+  assert.notEqual(match, null);
+  assert.match(match[1], /import\s*\{\s*initLevelSelect\s*\}\s*from\s*['"]\.\/level-select\.js['"];?/u);
+  assert.match(match[1], /initLevelSelect\(\s*\{\s*document,\s*fetchImpl:\s*fetch\s*\}\s*\);?/u);
+});
+
+test('validateLevels exposes the frontend payload contract', () => {
+  assert.equal(validateLevels(validLevels()), true);
+  assert.equal(validateLevels(null), false);
+  assert.equal(validateLevels([]), false);
+});
