+'use strict';
+
+const ALLOWED_DIFFICULTIES = new Set(['简单', '普通', '困难']);
+const LEVEL_COUNT = 5;
+
+function isNonEmptyString(value) {
+  return typeof value === 'string' && value.trim() !== '';
+}
+
+function validateLevels(value) {
+  if (!Array.isArray(value) || value.length !== LEVEL_COUNT) {
+    return false;
+  }
+
+  const ids = new Set();
+  return value.every((level) => {
+    if (
+      !level ||
+      !isNonEmptyString(level.id) ||
+      !isNonEmptyString(level.name) ||
+      !ALLOWED_DIFFICULTIES.has(level.difficulty) ||
+      typeof level.unlocked !== 'boolean'
+    ) {
+      return false;
+    }
+
+    if (ids.has(level.id)) {
+      return false;
+    }
+    ids.add(level.id);
+    return true;
+  });
+}
+
+function renderLevel(document, level) {
+  const item = document.createElement('li');
+  item.setAttribute('class', level.unlocked ? 'level-item unlocked' : 'level-item locked');
+
+  const button = document.createElement('button');
+  button.setAttribute('type', 'button');
+  button.setAttribute('data-level-id', level.id);
+  button.disabled = !level.unlocked;
+
+  const name = document.createElement('span');
+  name.textContent = level.name;
+
+  const difficulty = document.createElement('span');
+  difficulty.setAttribute('class', 'difficulty');
+  difficulty.textContent = level.difficulty;
+
+  const status = document.createElement('span');
+  status.setAttribute('class', 'status');
+  status.textContent = level.unlocked ? '可进入' : '未解锁';
+
+  name.appendChild(difficulty);
+  button.appendChild(name);
+  button.appendChild(status);
+  item.appendChild(button);
+  return item;
+}
+
+async function initLevelSelect({ document, fetchImpl = globalThis.fetch } = {}) {
+  if (!document) {
+    throw new TypeError('initLevelSelect requires a document');
+  }
+  if (typeof fetchImpl !== 'function') {
+    throw new TypeError('initLevelSelect requires fetchImpl');
+  }
