function createServer(options = {}) {
  const dataPath = options.dataPath ?? path.join(process.cwd(), 'data', 'levels.json');
  const staticRoot = options.staticRoot ?? path.join(process.cwd(), 'web');

  return http.createServer(async (request, response) => {
    if (request.url === '/api/levels') {
      if (request.method !== 'GET') {
        sendJson(response, 405, {
          error: {
            code: 'METHOD_NOT_ALLOWED',
            message: '不支持的请求方法',
          },
        });
        return;
      }

      try {
        const levels = await readLevels(dataPath);
        sendJson(response, 200, levels);
      } catch {
        sendJson(response, 500, { error: LEVEL_DATA_ERROR });
      }
      return;
    }

    let requestPath;
    try {
      requestPath = decodeURIComponent(request.url.split('?')[0]);
    } catch {
      sendText(response, 404, '静态资源不存在');
      return;
    }

    if (!requestPath.startsWith('/api/')) {
      await serveStatic(request, response, staticRoot);
      return;
    }

    sendJson(response, 404, {
      error: {
        code: 'API_NOT_FOUND',
        message: '请求的接口不存在',
      },
    });
  });
}

async function start(options = {}) {
  const port = options.port ?? Number(process.env.PORT ?? 3000);
  const server = createServer(options);
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, '127.0.0.1', resolve);
  });

  const address = server.address();
  return {
    origin: `http://127.0.0.1:${address.port}`,
    port: address.port,
    stop: () =>
      new Promise((resolve, reject) => {
        server.close((error) => {
          if (error) {
            reject(error);
            return;
          }
          resolve();
        });
      }),
  };
}

module.exports = {
  createServer,
  resolveStaticPath,
  start,
};

